@Override
    public void aiStep() {
        speedMult = codechicken.lib.math.MathHelper.approachLinear(speedMult, phaseManager.getCurrentPhase().getGuardianSpeed(), 0.1);
        if (this.level().isClientSide) {
            this.setHealth(this.getHealth());
            if (!this.isSilent()) {
                float f = Mth.cos(this.flapTime * ((float) Math.PI * 2F));
                float f1 = Mth.cos(this.oFlapTime * ((float) Math.PI * 2F));
                if (f1 <= -0.3F && f >= -0.3F) {
                    this.level().playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.ENDER_DRAGON_FLAP, this.getSoundSource(), 5.0F, 0.8F + this.random.nextFloat() * 0.3F, false);
                }

                if (!this.phaseManager.getCurrentPhase().getIsStationary() && --this.growlTime < 0) {
                    this.level().playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.ENDER_DRAGON_GROWL, this.getSoundSource(), 2.5F, 0.8F + this.random.nextFloat() * 0.3F, false);
                    this.growlTime = 200 + this.random.nextInt(200);
                }
            }
        }

        this.oFlapTime = this.flapTime;
        if (this.isDeadOrDying()) {
            float randX = (this.random.nextFloat() - 0.5F) * 8.0F;
            float randY = (this.random.nextFloat() - 0.5F) * 4.0F;
            float randZ = (this.random.nextFloat() - 0.5F) * 8.0F;
            this.level().addParticle(ParticleTypes.EXPLOSION, this.getX() + (double) randX, this.getY() + 2.0D + (double) randY, this.getZ() + (double) randZ, 0.0D, 0.0D, 0.0D);
        } else {
            this.updateDragonEnderCrystal();
            Vec3 vec3 = this.getDeltaMovement();
            float f = 0.2F / ((float) vec3.horizontalDistance() * 10.0F + 1.0F);
            f = f * (float) Math.pow(2.0D, vec3.y);
            if (this.phaseManager.getCurrentPhase().getIsStationary()) {
                this.flapTime += 0.1F;
            } else if (this.slowed) {
                this.flapTime += f * 0.5F;
            } else {
                this.flapTime += f;
            }

            this.setYRot(Mth.wrapDegrees(this.getYRot()));
            if (this.isNoAi()) {
                this.flapTime = 0.5F;
            } else {
                if (this.ringBufferIndex < 0) {
                    for (int i = 0; i < this.ringBuffer.length; ++i) {
                        this.ringBuffer[i][0] = this.getYRot();
                        this.ringBuffer[i][1] = this.getY();
                    }
                }

                if (++this.ringBufferIndex == this.ringBuffer.length) {
                    this.ringBufferIndex = 0;
                }

                this.ringBuffer[this.ringBufferIndex][0] = this.getYRot();
                this.ringBuffer[this.ringBufferIndex][1] = this.getY();
                if (this.level().isClientSide) {
                    if (this.lerpSteps > 0) {
                        double d7 = this.getX() + (this.lerpX - this.getX()) / (double) this.lerpSteps;
                        double d0 = this.getY() + (this.lerpY - this.getY()) / (double) this.lerpSteps;
                        double d1 = this.getZ() + (this.lerpZ - this.getZ()) / (double) this.lerpSteps;
                        double d2 = Mth.wrapDegrees(this.lerpYRot - (double) this.getYRot());
                        this.setYRot((float) ((double) this.getYRot() + d2 / (double) this.lerpSteps));
                        this.setXRot((float) ((double) this.getXRot() + (this.lerpXRot - (double) this.getXRot()) / (double) this.lerpSteps));
                        --this.lerpSteps;
                        this.setPos(d7, d0, d1);
                        this.setRot(this.getYRot(), this.getXRot());
                    }

                    this.phaseManager.getCurrentPhase().clientTick();
                } else {
                    IPhase iphase = this.phaseManager.getCurrentPhase();
                    iphase.serverTick();
                    if (this.phaseManager.getCurrentPhase() != iphase) {
                        iphase = this.phaseManager.getCurrentPhase();
                        iphase.serverTick();
                    }

                    phaseManager.globalServerTick();

                    Vec3 targetLocation = iphase.getTargetLocation();
                    if (targetLocation != null) {
                        double tRelX = targetLocation.x - this.getX();
                        double tRelY = targetLocation.y - this.getY();
                        double tRelZ = targetLocation.z - this.getZ();
                        double distanceSq = tRelX * tRelX + tRelY * tRelY + tRelZ * tRelZ;
                        float maxRiseOrFall = iphase.getMaxRiseOrFall();
                        double distanceXZ = Math.sqrt(tRelX * tRelX + tRelZ * tRelZ);
                        if (distanceXZ > 0.0D) {
                            if (phaseManager.getCurrentPhase().highVerticalAgility()) {
                                tRelY = Mth.clamp(tRelY, -maxRiseOrFall, maxRiseOrFall);
                            } else {
                                tRelY = Mth.clamp(tRelY / distanceXZ, -maxRiseOrFall, maxRiseOrFall);
                            }
                        }

                        this.setDeltaMovement(this.getDeltaMovement().add(0.0D, tRelY * 0.01D, 0.0D));
                        this.setYRot(Mth.wrapDegrees(this.getYRot()));
                        //Angle of target relative to current yaw clamped to +-50
                        double relTargetAngle = Mth.clamp(Mth.wrapDegrees(180.0D - Mth.atan2(tRelX, tRelZ) * (double) (180F / (float) Math.PI) - (double) this.getYRot()), -50.0D, 50.0D);
                        if (Math.abs(relTargetAngle) < 5) {
                            relTargetAngle *= speedMult * 5; //This is a hack to help line up with the target better when traveling at higher than normal speed.
                        }


                        Vec3 targetVector = targetLocation.subtract(this.getX(), this.getY(), this.getZ()).normalize();
                        Vec3 vector3d2 = new Vec3(
                                Mth.sin(this.getYRot() * ((float) Math.PI / 180F)),
                                this.getDeltaMovement().y,
                                -Mth.cos(this.getYRot() * ((float) Math.PI / 180F)))
                                .normalize();
                        float f8 = Math.max(((float) vector3d2.dot(targetVector) + 0.5F) / 1.5F, 0.0F);
                        this.yRotA *= 0.8F;
                        this.yRotA = (float) ((double) this.yRotA + relTargetAngle * (double) iphase.getYawFactor());
                        this.setYRot(getYRot() + (this.yRotA * 0.1F));
                        float f9 = (float) (2.0D / (distanceSq + 1.0D));
                        float f10 = 0.06F;
                        this.moveRelative(f10 * (f8 * f9 + (1.0F - f9)), new Vec3(0.0D, 0.0D, -1D));
                        if (this.slowed) {
                            this.move(MoverType.SELF, this.getDeltaMovement().scale(0.8F).scale(speedMult));
                        } else {
                            this.move(MoverType.SELF, this.getDeltaMovement().scale(speedMult));
                        }
                        Vec3 vector3d3 = this.getDeltaMovement().normalize();
                        double d6 = 0.8D + 0.15D * (vector3d3.dot(vector3d2) + 1.0D) / 2.0D;
                        this.setDeltaMovement(this.getDeltaMovement().multiply(d6, 0.91F, d6));
                    }
                }

                this.yBodyRot = this.getYRot();
                Vec3[] avector3d = new Vec3[this.dragonParts.length];

                for (int j = 0; j < this.dragonParts.length; ++j) {
                    avector3d[j] = new Vec3(this.dragonParts[j].getX(), this.dragonParts[j].getY(), this.dragonParts[j].getZ());
                }

                float f15 = (float) (this.getLatencyPos(5, 1.0F)[1] - this.getLatencyPos(10, 1.0F)[1]) * 10.0F * ((float) Math.PI / 180F);
                float f16 = Mth.cos(f15);
                float f2 = Mth.sin(f15);
                float f17 = this.getYRot() * ((float) Math.PI / 180F);
                float f3 = Mth.sin(f17);
                float f18 = Mth.cos(f17);
                this.setPartPosition(this.dragonPartBody, f3 * 0.5F, 0.0D, -f18 * 0.5F);
                this.setPartPosition(this.dragonPartRightWing, f18 * 4.5F, 2.0D, f3 * 4.5F);
                this.setPartPosition(this.dragonPartLeftWing, f18 * -4.5F, 2.0D, f3 * -4.5F);
                if (level() instanceof ServerLevel serverLevel && this.hurtTime == 0) {
                    this.collideWithEntities(serverLevel, this.level().getEntities(this, this.dragonPartRightWing.getBoundingBox().inflate(4.0D, 2.0D, 4.0D).move(0.0D, -2.0D, 0.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR));
                    this.collideWithEntities(serverLevel, this.level().getEntities(this, this.dragonPartLeftWing.getBoundingBox().inflate(4.0D, 2.0D, 4.0D).move(0.0D, -2.0D, 0.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR));
                    this.attackEntitiesInList(this.level().getEntities(this, this.dragonPartHead.getBoundingBox().inflate(1.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR));
                    this.attackEntitiesInList(this.level().getEntities(this, this.dragonPartNeck.getBoundingBox().inflate(1.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR));
                }

                float f4 = Mth.sin(this.getYRot() * ((float) Math.PI / 180F) - this.yRotA * 0.01F);
                float f19 = Mth.cos(this.getYRot() * ((float) Math.PI / 180F) - this.yRotA * 0.01F);
                float f5 = this.getHeadAndNeckYOffset();
                this.setPartPosition(this.dragonPartHead, f4 * 6.5F * f16, f5 + f2 * 6.5F, -f19 * 6.5F * f16);
                this.setPartPosition(this.dragonPartNeck, f4 * 5.5F * f16, f5 + f2 * 5.5F, -f19 * 5.5F * f16);
                double[] adouble = this.getLatencyPos(5, 1.0F);

                for (int k = 0; k < 3; ++k) {
                    DraconicGuardianPartEntity enderdragonpartentity = null;
                    if (k == 0) {
                        enderdragonpartentity = this.dragonPartTail1;
                    }

                    if (k == 1) {
                        enderdragonpartentity = this.dragonPartTail2;
                    }

                    if (k == 2) {
                        enderdragonpartentity = this.dragonPartTail3;
                    }

                    double[] adouble1 = this.getLatencyPos(12 + k * 2, 1.0F);
                    float f7 = this.getYRot() * ((float) Math.PI / 180F) + this.simplifyAngle(adouble1[0] - adouble[0]) * ((float) Math.PI / 180F);
                    float f20 = Mth.sin(f7);
                    float f21 = Mth.cos(f7);
                    float f22 = 1.5F;
                    float f23 = (float) (k + 1) * 2.0F;
                    this.setPartPosition(enderdragonpartentity, -(f3 * 1.5F + f20 * f23) * f16, adouble1[1] - adouble[1] - (double) ((f23 + 1.5F) * f2) + 1.5D, (f18 * 1.5F + f21 * f23) * f16);
                }

                if (!this.level().isClientSide) {
                    this.slowed = this.destroyBlocksInAABB(this.dragonPartHead.getBoundingBox()) | this.destroyBlocksInAABB(this.dragonPartNeck.getBoundingBox()) | this.destroyBlocksInAABB(this.dragonPartBody.getBoundingBox());
                    if (this.fightManager != null) {
                        this.fightManager.guardianUpdate(this);
                    }
                }

                for (int l = 0; l < this.dragonParts.length; ++l) {
                    this.dragonParts[l].xo = avector3d[l].x;
                    this.dragonParts[l].yo = avector3d[l].y;
                    this.dragonParts[l].zo = avector3d[l].z;
                    this.dragonParts[l].xOld = avector3d[l].x;
                    this.dragonParts[l].yOld = avector3d[l].y;
                    this.dragonParts[l].zOld = avector3d[l].z;
                }

            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (!this.level.isClientSide) {
            if (this.tickCount % 2 == 0) {
                if (this.level instanceof ServerLevel serverLevel) {
                    ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ModParticleTypes.FLY.get(), this);
                }
            }
            if (this.getTarget() != null) {
                this.navigation.moveTo(this.getTarget(), 7.0D);
            } else {
                Vec3 vec3 = LandRandomPos.getPos(this, 10, 7);
                if (vec3 == null){
                    vec3 = DefaultRandomPos.getPos(this, 10, 7);
                }
                if (vec3 != null){
                    this.navigation.moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
                }
            }
            if (this.level.collidesWithSuffocatingBlock(this, this.getBoundingBox().move(0.0D, -1.0D, 0.0D))) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.02D, 0.0D));
            } else {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.008D, 0.0D));
            }
            if (!this.moveControl.hasWanted()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(0.95F, 1.0F, 0.95F));
            }
            float inflate = 2.0F - this.getBbWidth() * 0.5F;
            for (LivingEntity living : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(inflate))) {
                if (living != this && !MobUtil.areAllies(this, living) && SummonTargetGoal.predicate(this).test(living)) {
                    if (living.hurt(ModDamageSource.swarm(this, this.getTrueOwner()), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE))) {
                        this.playSound(ModSounds.INSECT_SWARM_BITE.get(), 1.0F, this.getVoicePitch());
                        int speed = (int) ((this.getHealth() / this.getMaxHealth()) * 5);
                        living.invulnerableTime = Math.min(20, (20 - speed));
                        this.hurt(this.damageSources().starve(), 2.0F);
                        if (this.getTrueOwner() != null && CuriosFinder.hasWildRobe(this.getTrueOwner())){
                            living.addEffect(new MobEffectInstance(GoetyEffects.ACID_VENOM.get(), MathHelper.secondsToTicks(5)));
                        }
                    }
                }
            }
        }
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)) {
            potency += WandUtil.getPotencyLevel(caster);
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
            range += WandUtil.getRangeLevel(caster);
        }
        float damage = this.damage + potency;
        if (!worldIn.isClientSide) {
            for (Entity target : getBreathTarget(caster, range)) {
                if (target != null) {
                    if (target.hurt(ModDamageSource.swarm(caster, caster), damage)){
                        if (rightStaff(staff)) {
                            if (target instanceof LivingEntity livingTarget) {
                                MobEffect mobEffect = MobEffects.POISON;
                                if (CuriosFinder.hasWildRobe(caster)) {
                                    mobEffect = GoetyEffects.ACID_VENOM.get();
                                }
                                livingTarget.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(5) * duration));
                            }
                        }
                        if (!target.isAlive()){
                            InsectSwarm insectSwarm = new InsectSwarm(worldIn, caster, target.position());
                            insectSwarm.setLimitedLife(200 * duration);
                            if (potency > 0){
                                insectSwarm.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), potency - 1, false, false));
                            }
                            worldIn.addFreshEntity(insectSwarm);
                        }
                    }
                }
            }
        }
        this.playSound(worldIn, caster, ModSounds.INSECT_SWARM.get(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
    }

@Override
    public void lifeSpanDamage() {
        this.dismiss();
    }

@Override
    public void dismiss() {
        this.discard();
    }

default void ownedTick(){
        if (this instanceof Mob mobThis) {
            if (!mobThis.level.isClientSide) {
                if (this.getTrueOwner() instanceof IOwned owned) {
                    try {
                        if (owned.getHasSummonCheck() <= 0) {
                            owned.setHasSummonCheck(2);
                        }
                    } catch (NullPointerException ignored) {
                    }
                    if (this.getTrueOwner().isRemoved() || this.getTrueOwner().isDeadOrDying() || !this.getTrueOwner().isAlive()) {
                        if (owned.getTrueOwner() != null) {
                            this.setTrueOwner(owned.getTrueOwner());
                        } else if (!this.isHostile() && !this.isNatural() && !(owned instanceof Enemy) && !owned.isHostile()) {
                            mobThis.kill();
                        }
                    }
                }
                this.ownerCheck();
                this.targetingTick();
                if (this.getTrueOwner() instanceof Mob mobOwner) {
                    if (mobOwner instanceof Apostle apostle) {
                        if (mobThis.distanceTo(apostle) > 32) {
                            this.teleportTowards(apostle);
                        }
                    }
                    if (mobOwner.getType().is(Tags.EntityTypes.BOSSES) || mobOwner.getType().is(ModTags.EntityTypes.SUMMON_KILL)) {
                        if (mobOwner.isRemoved() || mobOwner.isDeadOrDying()) {
                            mobThis.kill();
                        }
                    }
                }
                this.mobSense();
                if (this.hasLifespan()) {
                    this.setLifespan(this.getLifespan() - 1);
                    if (this.getLifespan() <= 1) {
                        this.lifeSpanDamage();
                    }
                }
                if (this.getHasSummonCheck() > 0) {
                    this.setHasSummonCheck(this.getHasSummonCheck() - 1);
                }
                if (this.getRevivingTime() > 0) {
                    this.reviveTick();
                    this.setRevivingTime(this.getRevivingTime() - 1);
                }
                if (this.getPacifyTick() > 0) {
                    this.pacify();
                    this.setPacifyTick(this.getPacifyTick() - 1);
                }
            }
        }
    }

default void setLimitedLife(int limitedLifeTicksIn) {
        this.setHasLifespan(true);
        this.setLifespan(limitedLifeTicksIn);
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!this.world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){
				// This is if the firebomb gets a direct hit
				float damage = Spells.firebomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FIRE).setProjectile(),
						damage);

				if(!MagicDamage.isEntityImmune(DamageType.FIRE, entityHit))
					entityHit.setFire(Spells.firebomb.getProperty(Spell.BURN_DURATION).intValue());
			}

			// Notify clients to play the explosion effect
			WizardryPacketHandler.net.sendToAllAround(
					new PacketBombExplosion.Message(PacketBombExplosion.FIREBOMB, posX, posY, posZ, blastMultiplier),
					new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

			this.playSound(WizardrySounds.ENTITY_FIREBOMB_SMASH, 1.5F, rand.nextFloat() * 0.4F + 0.6F);
			this.playSound(WizardrySounds.ENTITY_FIREBOMB_FIRE, 1, 1);

			double range = Spells.firebomb.getProperty(Spell.BLAST_RADIUS).floatValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(range, this.posX, this.posY,
					this.posZ, this.world);

			for(EntityLivingBase target : targets){
				if(target != entityHit && target != this.getThrower()
						&& !MagicDamage.isEntityImmune(DamageType.FIRE, target)){
					// Splash damage does not count as projectile damage
					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FIRE),
							Spells.firebomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);
					target.setFire(Spells.firebomb.getProperty(Spell.BURN_DURATION).intValue());
				}
			}
		}

		this.setDead();
	}

@Override
	public IMessage onMessage(Message message, MessageContext ctx){
		if(ctx.side.isClient()){
			net.minecraft.client.Minecraft.getMinecraft().addScheduledTask(
					() -> Wizardry.proxy.handleBombExplosionPacket(message));
		}
		return null;
	}

@Override
	public void handleBombExplosionPacket(PacketBombExplosion.Message message){

		net.minecraft.world.World world = Minecraft.getMinecraft().world;
		double x = message.x, y = message.y, z = message.z;
		float blastMultiplier = message.blastMultiplier;

		switch(message.bombType){

			case PacketBombExplosion.FIREBOMB:
				ParticleBuilder.create(Type.FLASH).pos(x, y, z).scale(5 * blastMultiplier).clr(1, 0.6f, 0).spawn(world);
				for(int i = 0; i < 60 * blastMultiplier; i++){
					ParticleBuilder.create(Type.MAGIC_FIRE, world.rand, x, y, z, 2 * blastMultiplier, false)
							.time(10 + world.rand.nextInt(4)).scale(2 + world.rand.nextFloat()).spawn(world);
					ParticleBuilder.create(Type.DARK_MAGIC, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(1.0f, 0.2f + world.rand.nextFloat() * 0.4f, 0.0f).spawn(world);
				}
				world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, x, y, z, 0, 0, 0);
				break;

			case PacketBombExplosion.POISON_BOMB:
				ParticleBuilder.create(Type.FLASH).pos(x, y, z).scale(5 * blastMultiplier)
						.clr(0.2f + world.rand.nextFloat() * 0.3f, 0.6f, 0.0f).spawn(world);
				for(int i = 0; i < 60 * blastMultiplier; i++){
					ParticleBuilder.create(Type.SPARKLE, world.rand, x, y, z, 2 * blastMultiplier, false).time(35)
							.scale(2).clr(0.2f + world.rand.nextFloat() * 0.3f, 0.6f, 0.0f).spawn(world);
					ParticleBuilder.create(Type.DARK_MAGIC, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(0.2f + world.rand.nextFloat() * 0.2f, 0.8f, 0.0f).spawn(world);
				}
				world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, x, y, z, 0, 0, 0);
				break;

			case PacketBombExplosion.SMOKE_BOMB:
				ParticleBuilder.create(Type.FLASH).pos(x, y, z).scale(5 * blastMultiplier).clr(0, 0, 0).spawn(world);
				world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, x, y, z, 0, 0, 0);
				for(int i = 0; i < 60 * blastMultiplier; i++){
					float brightness = world.rand.nextFloat() * 0.1f + 0.1f;
					ParticleBuilder.create(Type.CLOUD, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(brightness, brightness, brightness).time(80 + world.rand.nextInt(12)).shaded(true).spawn(world);
					brightness = world.rand.nextFloat() * 0.3f;
					ParticleBuilder.create(Type.DARK_MAGIC, world.rand, x, y, z, 2 * blastMultiplier, false)
							.clr(brightness, brightness, brightness).spawn(world);
				}
				break;

			case PacketBombExplosion.SPARK_BOMB:
				ParticleBuilder.spawnShockParticles(world, x, y, z);
				for(int id : message.secondaryTargetIDs){
					net.minecraft.entity.Entity target = world.getEntityByID(id);
					if(target instanceof net.minecraft.entity.EntityLivingBase){
						ParticleBuilder.create(Type.LIGHTNING).pos(x, y, z).target(target).spawn(world);
						ParticleBuilder.spawnShockParticles(world, target.posX,
								target.posY + target.height / 2, target.posZ);
					}
				}
				break;
		}
	}
